(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["haw"] = {"ui":{"skip":"E lele i ka ʻike","back":"← E hoʻi i AI-gile","lang.button":"ʻŌlelo: {name}","lang.dialog":"E koho i kahi ʻōlelo","lang.search":"E ʻimi i nā ʻōlelo","lang.none":"ʻAʻohe ʻōlelo kūpono","lang.notYet":"ʻAʻole i unuhi ʻia ka {name}","theme.aria":"E hoʻololi ma waena o ke ʻano ʻālohilohi a me ke ʻano ʻeleʻele","theme.toLight":"E hoʻololi i ke ʻano ʻālohilohi","theme.toDark":"E hoʻololi i ke ʻano ʻeleʻele","words.underline":"E kaha lalo i kēia mau hua ʻōlelo ma ka ʻaoʻao","words.underlineHelp":"E kau i ka ʻiole ma luna o kekahi hua ʻōlelo kiko, a i ʻole e paʻi iā ia, e ʻike ai i kona manaʻo.","index.title":"AI-gile: kāu pūʻulu hoʻomohala AI, ma hoʻokahi papa","index.description":"He papa kanban ʻo AI-gile no nā pūʻulu hoʻopaʻa code AI. Ke hana nei lākou i kou hiamoe ʻana; loaʻa iā ʻoe kekahi puʻu pōkole o nā mea e hoʻoholo ai, e hoʻāʻo ai a e ʻae ai.","hero.logoAlt":"Hōʻailona papa AI-gile","hero.h1.html":"Kāu pūʻulu hoʻomohala AI, ma hoʻokahi&nbsp;papa.","hero.alpha":"🐣 Pre-alpha pani ʻia","hero.alphaTitle":"Ma ka hoʻomaka a ʻaʻole i pau: mahalo no ka hoʻāʻo ʻana!","hero.lede":"Hana lākou i kou hiamoe ʻana. Ala ʻoe i kekahi puʻu pōkole: kekahi mau nīnau, kekahi mau mea e hoʻāʻo ai, hoʻokahi a ʻelua paha daimana poni. E kaomi, e ʻae, a e hoʻi i kāu kope.","dl.windows":"ʻApp Windows","dl.browser":"E holo ma kāu polokalamu kele","dl.soon":"E hiki mai ana","dl.notify":"🔔 E haʻi mai iaʻu ke wehe ʻia","dl.notifySmall":"Alpha a i ʻole beta","hero.secondary":"Agile, akā ʻaʻole pono i ka pūʻulu ke kope kū o ka hālāwai. (Hālāwai nō naʻe lākou.)","pitch.h2":"AI-gile i nā huaʻōlelo he nui a he liʻiliʻi e like me kāu makemake","pitch.lede":"E koho i ka lōʻihi, mai ka huaʻōlelo hoʻokahi a i 144. He wehewehe ponoʻī kēlā me kēia lōʻihi, i kākau ʻia no ia nui. E huki i ka ʻōwili a i ʻole e hoʻohana i nā pihi pua.","pitch.rangeLabel":"Ka lōʻihi ma nā huaʻōlelo","pitch.dice":"🎲 kekahi mana ʻē aʻe","pitch.words.one":"{n} huaʻōlelo","pitch.words.other":"{n} huaʻōlelo","pitch.letters.one":"{n} leka","pitch.letters.other":"{n} leka","pitch.chars.one":"{n} hōʻailona","pitch.chars.other":"{n} hōʻailona","count.line.html.one":"{n} kāleka ma ka papa i kēia manawa","count.line.html.other":"{n} kāleka ma ka papa i kēia manawa","features.aria":"Ka mea āna e hana ai","f.pile.h":"Hoʻokahi puʻu no ʻoe","f.pile.html":"Mālama ʻo <b>No ʻoe</b> i nā mea a pau e kali nei iā ʻoe, ma nā papahana a pau: nā nīnau, nā mea e hoʻāʻo ai, nā hana hiki i ke kanaka wale nō. Ua ʻōlelo kāu laina i ka mea aʻe a me ka lōʻihi o ka manawa.","f.sleep.h":"Nā pūʻulu hana i kou hiamoe ʻana","f.sleep.p":"He alakaʻi a he pūʻulu mea hana AI kā kēlā me kēia papahana. E ʻōlelo ma kekahi kāleka a ala ka pūʻulu, hana i ka hana, a hoʻihoʻi me nā ʻanuʻu hiki i ke kanaka luhi ke hahai.","f.tester.h":"Nānā mua ka mea hoʻāʻo AI","f.tester.p":"Ma mua o ka hiki ʻana mai o kekahi mea iā ʻoe, hahai ka mea hoʻāʻo i nā ʻanuʻu ma kahi kope o ka ʻapp a hōʻike i kāna i ʻike ai, me ke kiʻi pale. E nānā wikiwiki i ka mea i pono a e ʻae me ke kaomi hoʻokahi.","f.proof.h":"He hōʻike, ʻaʻole he hoʻohiki","f.proof.p":"Hōʻike kēlā me kēia hāʻawi i ka mea i loli: nā waihona, ka ʻokoʻa, nā kiʻi pale. ʻAʻole pono e wehe i kēlā me kēia ʻapp e ʻike ai ua pau.","f.chat.h":"E kamaʻilio me kou mau alakaʻi","f.chat.p":"He alahaka e like me Discord: hoʻokahi hōʻailona no kēlā me kēia papahana, nā daimana poni no ka mea e makemake ana iā ʻoe. E hoʻouna i kahi manaʻo i ka alakaʻi; hoʻololi ʻo ia i mau kāleka a me ka manaʻo hana, me ke pihi ✅ Go.","f.tidy.h":"Mālama i ia iho","f.tidy.p":"Hui nā kāleka pili i hoʻokahi, hoʻoponopono ʻia nā poʻo inoa pohihihi, a mālama ka nānā token i ke code i māmā. ʻOi aku ka liʻiliʻi o nā mea e hoʻololi ai, ka liʻiliʻi o ka noʻonoʻo.","f.private.h":"Nou, ma kāu kamepiula","f.private.li1":"Holo ka papa ma kāu mīkini ponoʻī a pane iā ʻoe wale nō.","f.private.li2":"Ua hūnā ʻia nā DM pilikino ma waena o nā kānaka mai ke kiko a i ke kiko.","f.private.li3":"ʻAʻohe moʻokāki, ʻaʻohe mea alualu, ʻaʻohe kuki.","f.lang.h":"Ma kāu ʻōlelo","f.lang.p":"Ma luna o 120 ʻōlelo, mai ka Holani, ka Wales a me ka Kepani a hiki i ka ʻōlelo pailaka, ʻo Yoda a me Klingon, me ka hoʻololi wikiwiki i ka Pelekānia no nā huaʻōlelo mea hoʻomohala.","tl.aria":"Laina manawa mai ka kamaʻilio mua a hiki i ke ala e hiki mai ana","tl.h2":"Mai ka kamaʻilio mua a i ka mea e hiki mai ana","tl.lede":"Nā lā a me nā manawa maoli, ma kou wā ponoʻī. Ma hope o kēia lā he hoʻolālā ia, ʻaʻohe lā i hoʻohiki ʻia.","tl.today":"Kēia lā","tl.planned":"hoʻolālā ʻia","tl.cards.one":"{n} kāleka","tl.cards.other":"{n} kāleka","join.h2":"E komo mai","join.lede":"Ke kūkulu ʻia nei ʻo AI-gile e ke kanaka liʻiliʻi a me nā mea hana ʻoli he nui. He pilikino ia i kēia manawa, ma ka alpha pani ʻia me nā hoaaloha. Makemake ʻoe e hoʻāʻo ke wehe ʻia?","join.btn":"E kākau i kou hoihoi","join.small":"E leka uila aku mākou iā ʻoe, ʻaʻohe mea ʻē aʻe","footer.tag":"AI-gile. ʻAʻohe mea alualu, ʻaʻohe kuki, ʻaʻohe kope kū hālāwai.","footer.licence":"ʻAe ʻoihana","footer.status":"Kūlana","footer.privacy":"Ka mea a mākou e mālama ai","form.sending":"Ke hoʻouna nei…","form.failed":"ʻAʻole i hana kēlā: e hoʻāʻo hou ma hope.","form.offline":"ʻAʻole hiki ke hōʻea iā AI-gile: e hoʻāʻo hou ma hope.","form.keep":"Hoʻohana mākou i kēia no ka pane ʻana iā ʻoe wale nō, a laila holoi mākou. ʻAʻohe mea alualu, ʻaʻohe kuki.","form.keepLink":"Ka mea a mākou e mālama ai","interest.title":"AI-gile: e haʻi mai iaʻu ke wehe ʻia ka alpha","interest.description":"E waiho i kāu leka uila e lohe ai i ka wā e wehe ai ka alpha a i ʻole ka beta pani ʻia o AI-gile.","interest.h1":"🔔 E haʻi mai iaʻu ke wehe ʻia","interest.lede":"Ma ka pre-alpha pani ʻia ʻo AI-gile. E waiho i kāu leka uila a e kākau aku mākou hoʻokahi manawa, ke loaʻa kahi wahi nou.","interest.email":"Kāu leka uila","interest.which":"ʻO ka hoʻāʻo ʻehea?","interest.alpha":"Alpha pani ʻia: mua, ʻōhūhū, nui nā loli","interest.beta":"Beta: ʻoi aku ka paʻa, ma hope","interest.both":"ʻO kekahi paha, ka mea e hiki mua mai","interest.submit":"E hoʻokomo iaʻu i ka papa inoa","interest.thanks":"Mahalo! Aia ʻoe ma ka papa inoa.","licence.title":"AI-gile: ʻae ʻoihana","licence.description":"Hoʻohana ʻoe iā AI-gile ma kāu ʻoihana? E noi i ka ʻae ʻoihana manuahi.","licence.h1":"📜 ʻAe ʻoihana","licence.lede":"Hoʻohana ʻoe iā AI-gile ma ka hana? E haʻi mai ʻo wai ʻoe a he aha kāu e hana nei. Inā he pono kāna hana, manuahi ka ʻae.","licence.company":"Hui","licence.website":"Pūnaewele","licence.what":"Kāu hana","licence.how":"Pehea ia e kōkua ai i ka honua","licence.email":"Leka uila","licence.submit":"E noi","licence.thanks":"Mahalo! E pane aku mākou ma ka leka uila.","status.title":"Kūlana AI-gile","status.h1":"Kūlana AI-gile","status.quiet":"Mālie nō","status.intro":"Ke hana nei anei ʻo AI-gile i kēia manawa? Nānā kēia ʻaoʻao i ka pūnaewele, ke kaʻana papa, nā kelepona a me ka hoʻoiho i kēlā me kēia 5 minuke.","status.up":"Ke hana nei (pane ʻia i loko o {ms} ms)","status.slow":"ʻAʻole i pane i ka nānā hope loa, ke hoʻāʻo hou nei","status.down":"Pio: ʻaʻole i pane i nā nānā hope ʻelua","status.svc.web":"Pūnaewele","status.svc.web.offers":"Kēia pūnaewele: he aha ʻo AI-gile, a me ka palapala hoihoi","status.svc.boards":"Kaʻana papa","status.svc.boards.offers":"Nā papa ākea, nā leka ma waena o nā hoaaloha a me nā kono","status.svc.calls":"Kelepona","status.svc.calls.offers":"Leo, wikiō a me ke kaʻana pale ma AI-gile","status.svc.download":"Hoʻoiho","status.svc.download.offers":"Ka mea hoʻokomo Windows a me nā loulou kono","status.checking":"Ke nānā nei…","status.offline":"ʻAʻole hiki ke hōʻea i ka lawelawe kūlana i kēia manawa (ke hoʻāʻo hou nei)","status.updated":"ua hōʻano hou ʻia {ago}","status.justNow":"i kēia manawa wale nō","status.min":"{n} minuke i hala","status.hours":"{n} hola i hala","status.days":"{n} lā i hala","privacy.title":"AI-gile: ka mea a mākou e mālama ai","privacy.h1":"Ka mea a mākou e mālama ai","privacy.lede":"Ma ke ʻano pōkole: ka mea āu e hoʻouna mai ai wale nō, ʻaʻole no ka manawa lōʻihi.","privacy.only":"Ka mea āu e hoʻouna mai ai wale nō: ka mea āu e kākau ai ma kekahi palapala, e like me kāu leka uila. ʻAʻohe mea ʻē aʻe e pili ana iā ʻoe.","privacy.sealed":"Hoʻopaʻa ʻia i ʻole e hiki i kā mākou kikowaena ke heluhelu: ma kāu polokalamu kele ma mua o kona haʻalele ʻana (ma kekahi polokalamu kele kahiko, i ka manawa e hōʻea ai). ʻO kā mākou papa ponoʻī wale nō ke hiki ke wehe.","privacy.server":"Holoi ʻia mai ke kikowaena aku i ka hōʻea ʻana i kā mākou papa. ʻO nā mea e koe ana ma laila ma hope o 30 lā, holoi ʻia nō.","privacy.board":"Mālama mākou ma kā mākou papa a hiki i ko mākou pane ʻana iā ʻoe, a laila holoi pū mākou ma laila.","privacy.none":"ʻAʻohe mea alualu, ʻaʻohe kuki, ʻaʻohe kālailai.","privacy.local":"Noho kāu ʻōlelo a me kāu koho mālamalama a pōʻeleʻele ma kāu polokalamu kele ponoʻī. ʻAʻole loa e hoʻouna ʻia mai iā mākou.","privacy.ask":"Makemake ʻoe e holoi koke ʻia? E pane i kā mākou leka uila a e haʻi mai.","live.h2":"E nānā i kona kūkulu ʻia ʻana, ola","live.caption":"Huna ʻia kēlā me kēia kāleka: ʻike ʻoe i ke ʻano o ka hana, ʻaʻole nā ʻōlelo.","live.watching.one":"ola: {n} e nānā ana","live.watching.other":"ola: {n} e nānā ana","live.last.now":"Ua neʻe ka pā hope loa i kēia manawa","live.last.min.one":"Ua neʻe ka pā hope loa {n} minuke aku nei","live.last.min.other":"Ua neʻe ka pā hope loa {n} minuke aku nei","live.last.hour.one":"Ua neʻe ka pā hope loa {n} hola aku nei","live.last.hour.other":"Ua neʻe ka pā hope loa {n} hola aku nei","live.last.day.one":"Ua neʻe ka pā hope loa {n} lā aku nei","live.last.day.other":"Ua neʻe ka pā hope loa {n} lā aku nei","live.offline":"Ke hoʻomaha iki nei ka papa ola. E hoʻi mai koke.","live.cols":"Backlog|E hana|Ke hana nei|Ke nānā nei ka pūʻulu|No ʻoe e test|No ka pūʻulu|Pau"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Hāʻawi."]},{"n":2,"texts":["Kanban robot.","Robot ʻoli.","Manaʻo, kūkulu."]},{"n":3,"texts":["Kanban no nā robot.","Lilo ka manaʻo hiʻona.","Kanban mea hana manuahi."]},{"n":5,"texts":["Papa kanban a nā mea hana.","Kākau kāleka. Kūkulu nā mea hana.","Manuahi, kūloko, hoʻāʻo ʻia, lealea iki."]},{"n":8,"texts":["Papa kanban manuahi, hana nā mea hana AI.","Kākau i manaʻo. Kūkulu nā mea hana. ʻAe ʻoe.","Agile no ke kanaka a me nā robot ʻoli."]},{"n":13,"texts":["Papa kanban ma kāu kamepiula, lawe nā mea hana AI i nā kāleka.","E kākau i kahi manaʻo. Kūkulu kekahi pūʻulu mea hana iā ia. Nānā ka mea hoʻāʻo.","Manuahi, ʻaʻohe moʻokāki a mea alualu: he papa, kekahi mau robot, a ʻo ʻoe ka luna."]},{"n":21,"texts":["He papa kanban ʻo AI-gile no ka hana pū me nā mea hana hoʻopaʻa code AI. Lawe lākou i nā kāleka; hoʻāʻo ʻoe a ʻae.","Loaʻa i ka papahana kēlā me kēia kahi alakaʻi a me pūʻulu mea hana AI. ʻŌlelo ma kekahi kāleka, hoʻomaka ka pūʻulu.","He papa hana pilikino manuahi e holo ana ma kāu kamepiula ponoʻī. He mau robot nā limahana. ʻO ʻoe ka mea e ʻōlelo ana ʻae."]},{"n":34,"texts":["Waiho ʻoe i nā manaʻo ma ka papa. Hoʻololi kekahi pūʻulu mea hana AI iā lākou i mau hiʻona hana, hoʻāʻo, a hoʻihoʻi me nā ʻanuʻu. ʻAʻohe mea i pau a ʻōlelo ʻoe.","He papa kanban hale ʻo AI-gile a Rich i kūkulu ai me ke kōkua o nā mea hana āna e alakaʻi nei. Manuahi, holo ma kāu kamepiula, kaʻana like me nā hoaaloha, ʻaʻole kūʻai.","E noʻonoʻo i kahi papa kanban maʻamau, me nā kolamu mai Backlog a Pau, akā lawe nā mea hana AI i nā kāleka. Hōʻike lākou i ka holomua, nīnau ke paʻa, a kali mau i kou ʻae ʻana."]},{"n":55,"texts":["He papa kanban ʻo AI-gile a he mau mea hana AI ka pūʻulu. He alakaʻi kā kēlā me kēia papahana nāna e hoʻolālā, a he mau kōkua nāna e kūkulu. Ke mākaukau kekahi hiʻona, hoʻāʻo ka mea hoʻāʻo AI a lawe i kiʻi pale, a hiki i kāu puʻu. E ʻae, a i ʻole e ʻōlelo a hana hou lākou.","Hoʻomaka ia ma ke ʻano he ala o hoʻokahi kanaka e mālama i nā hālāwai hoʻopaʻa code AI he nui i ka manawa hoʻokahi, a ulu ia i papa kūpono. Holo ia ma kāu mīkini, ʻaʻole noi i moʻokāki, a ʻaʻohe mea alualu. ʻAʻole naʻe i pau, no laila e manaʻo i nā ʻaoʻao ʻōhūhū a me kekahi mea e kāhāhā ai.","Eia ka mana ʻoiaʻiʻo. Pono nō ʻoe e loaʻa nā manaʻo a nānā i nā hopena. Hana ʻo AI-gile i nā mea ma waena: mālama i nā kāleka, hoʻāla i ka mea hana kūpono ke ʻōlelo ʻoe, hōʻike i ka mea i loli, a hōʻuluʻulu i hoʻokahi puʻu pōkole nou."]},{"n":89,"texts":["He papa kanban manuahi ʻo AI-gile e holo ana ma kāu kamepiula. Loaʻa i kēlā me kēia papahana kahi pūʻulu mea hana AI: he alakaʻi nāna e hoʻololi i kou mau manaʻo i kāleka a me hoʻolālā, a he mau kōkua nāna e lawe i nā kāleka. Ke kūkulu ʻia kekahi mea, hahai ka mea hoʻāʻo AI i nā ʻanuʻu a hōʻike i kāna i ʻike ai. A laila kali ia ma kahi puʻu i kapa ʻia No ʻoe. ʻAe ʻoe, a i ʻole ʻōlelo a hoʻāʻo hou ka pūʻulu. ʻAʻohe mea e hiki i Pau me ʻoe ʻole.","Aia kekahi mau hiʻona āu e manaʻo ʻole ai. Mālama ke kiaʻi pō i ke kolamu Hana i piha i kou hiamoe ʻana, me nā kāleka ʻaʻole pono i kāu pane. Hōʻike ka helu token i ka hoʻohana o kēia lā a me kēia pule, a ʻōlelo ke ʻano ʻAʻohe Hōʻailona e hoʻōki. Hiki iā ʻoe ke hoʻouna i nā leka i nā hoaaloha, hūnā ʻia mai ke kiko a i ke kiko. Kamaʻilio ka papa i kahi o 120 ʻōlelo, me ka Holani, ka pailaka a me Klingon. ʻAʻohe kumukūʻai, a ʻaʻohe mea e hoʻāʻo nei e kūʻai aku iā ʻoe.","He papahana liʻiliʻi pilikino ʻo AI-gile, ʻaʻole he hui. Makemake ʻo Rich e mālama i nā papahana hoʻopaʻa code AI he nui me ka wehe ʻole i kēlā me kēia ʻapp e nānā ai, no laila kūkulu ʻo ia a me nā mea hana i papa no ia, a laila hoʻohana i ka papa e kūkulu i ke koena. Aia ia ma ka pre-alpha pani ʻia, ʻo ia hoʻi, hana ia, ʻo ka hapa nui, no kekahi mau hoaaloha. ʻAʻohe ʻaoʻao kumukūʻai, ʻaʻohe nūhou leka, a ʻaʻohe hoʻolālā ulu. Inā ʻike ʻia he kōkua, hiki iā ʻoe ke noi e hoʻāʻo ke wehe ākea iki ʻia."]},{"n":144,"texts":["He papa kanban ʻo AI-gile no hoʻokahi kanaka a me nā mea hana AI he nui. Holo ia ma kāu kamepiula a manuahi loa. Hoʻohui ʻoe i nā papahana, a loaʻa i kēlā me kēia kahi alakaʻi a me kahi pūʻulu liʻiliʻi. Kamaʻilio ʻoe me ka alakaʻi, e like me Discord, a wehewehe i kahi manaʻo; hoʻololi ia i mau kāleka a me kahi hoʻolālā, a kali e kaomi ʻoe i Go. Hana ka pūʻulu ma nā kāleka ma ke ʻano koʻikoʻi, me kahi laina kauoha maʻalahi no nā kumu hoʻohālike ʻōlelo. Ma mua o ka hoʻi ʻana mai, hahai ka mea hoʻāʻo AI i nā ʻanuʻu ma kahi kope o ka ʻapp a hoʻohui i kiʻi pale. Hiki ka hana i pau i kāu puʻu me nā waihona i loli a me ka ʻokoʻa. ʻAe ʻoe, a i ʻole ʻōlelo ʻoe a hoʻāʻo hou ka pūʻulu. ʻO ʻoe wale nō hiki ke hoʻoneʻe i kāleka i Pau.","He lā me AI-gile, ma kahi o ia. I ke ahiahi waiho ʻoe i kekahi mau ʻōlelo: aia kēia pihi ma ka wahi hewa, pono e hoʻokaʻina ʻia kēlā papa inoa, hiki paha iā mākou ke loaʻa i ke ʻano ʻeleʻele. Hiamoe ʻoe. Heluhelu nā mea hana i nā ʻōlelo, hana i nā loli, hoʻāʻo iā lākou a hoʻihoʻi iā ʻoe. Inā hakahaka ka Hana, hoʻopiha ke kiaʻi pō iā ia mai ka backlog me nā kāleka ʻaʻole pono i kāu pane. I ke kakahiaka he hoʻokahi puʻu pōkole: ʻelua nīnau a me kekahi mau mea e hoʻāʻo ai, me nā ʻanuʻu hiki i ke kanaka hiamoe ke hahai a me kahi kiʻi pale e hana ana. Kaomi ʻoe, ʻae i ka maikaʻi a hoʻihoʻi i ke koena. Hōʻike ka helu token i ka mea i hoʻohana ʻia, a aia ke ʻano ʻAʻohe Hōʻailona no nā pule liʻiliʻi. A laila ʻai ʻoe i ka ʻaina kakahiaka, ʻaʻole hiki i nā mea hana ke kōkua.","ʻO ka mea mua, ka mea ʻaʻole ʻo AI-gile. ʻAʻole he hoʻomaka hui, ʻaʻole kūʻai ʻia, a ʻaʻohe mea e hōʻuluʻulu ana i kāu ʻikepili. He papa manuahi ia e holo ana ma kāu kamepiula, me ka moʻokāki ʻole, mea alualu ʻole a kuki ʻole. He wahi maikaʻi ia e ʻike ai i nā papahana hoʻopaʻa code AI a pau i ka manawa hoʻokahi, me kahi pūʻulu mea hana e hana ana i nā kāleka a ʻo ʻoe ka mea hoʻoholo. Hoʻohui ia i nā kāleka pili, hoʻoponopono i nā poʻo inoa pohihihi, a nānā i ka māmā o ke code. Kamaʻilio ia ma kahi o 120 ʻōlelo, mai ka Holani a i ka pailaka a me Klingon. Kūkulu ʻia e Rich a me nā mea hana ʻoli he nui. Aia ia ma ka pre-alpha pani ʻia, no laila ʻōhūhū ma kekahi mau wahi. Inā leʻaleʻa ia iā ʻoe, e noi me ke ahonui."]}],"quips":{"1":"Hoʻokahi huaʻōlelo. Wiwoʻole. Wiwoʻole loa paha.","3":"ʻEkolu huaʻōlelo. ʻOi aku ka pololei ma mua o ka hapa nui o nā ʻaoʻao huahana.","8":"ʻEwalu huaʻōlelo. Poto ma mua o ka hālāwai kū.","21":"He kiko moʻolelo nā lōʻihi, ma ke ala. ʻIo nō.","55":"Kanalimakūmālima huaʻōlelo. Pau ʻelua kāleka i kou heluhelu ʻana i kēia.","144":"ʻO ia ka mea lōʻihi. ʻAʻohe 233. Ua hele nā mea hana e hiamoe."}},"timeline":{"first-idea.name":"Ka manaʻo mua","first-idea.line":"Ka kamaʻilio mua loa, ma mua o ka loaʻa ʻana o kekahi code.","first-board.name":"Ka papa mua","first-board.line":"He papa e nānā ana i kona kūkulu ponoʻī: nā kāleka, nā kolamu, huki a kau, nā papahana.","team-roles.name":"Pūʻulu a me nā kuleana","team-roles.line":"Nā ʻano mea hana, nā kumu hoʻohālike pūʻulu, nā wahi a me ka mea nāna e hana i ka aha.","install.name":"Kau a me nā hoʻokuʻu","install.line":"He zip hiki i ke hoaaloha ke kau, hōʻano hou ponoʻī, nā kahawai a me ka hoʻi.","usage-saver.name":"Mālama hoʻohana","usage-saver.line":"E ana i ke kumukūʻai o nā holo, mālama i ke code i māmā, mālama i kou palena.","friends.name":"Nā hoaaloha a me ke kaʻana like","friends.line":"Nā DM pilikino, he relay hūnā ʻia, nā kono, nā kuleana a me nā papahana i kaʻana like ʻia.","languages.name":"Nā ʻōlelo","languages.line":"Kēlā me kēia kikokikona pale ma kahi waihona ʻōlelo, me ka Holani a me ka Flemish ma mua.","ai-tester.name":"Mea hoʻāʻo AI","ai-tester.line":"Nānā ka mea hoʻāʻo i kēlā me kēia hāʻawi ma mua a hōʻike i kāna i ʻike ai.","website.name":"Ka pūnaewele","website.line":"aigile.lol, ka teaser a me kēia laina manawa.","streaming.name":"Kamaʻilio a me ka kahe","streaming.line":"Discord, Twitch, OBS, ke ʻano kahe, GIF a me emoji.","no-ai.name":"Mana AI ʻole","no-ai.line":"He papa no ka poʻe hoʻopaʻa code me ka AI ʻole, a me nā papa lehulehu.","night-watch.name":"Kiaʻi pō","night-watch.line":"Mālama ke kiaʻi a me ka Scrum Master i nā pūʻulu ma ka hana i kou hiamoe ʻana.","p-more.name":"Nā mea ʻē aʻe a pau","p-more.line":"Nā manaʻo liʻiliʻi e kali ana i ko lākou wā.","p-android.name":"Kelepona a me Android","p-android.line":"E hōʻea i kāu papa mai kahi kelepona, a laila he ʻapp Android maoli.","p-release.name":"Alpha a ma hope aku","p-release.line":"Alpha pani ʻia, ka pūnaewele ola, a laila beta.","p-languages.name":"Nā ʻōlelo hou aʻe","p-languages.line":"Ma luna o hoʻokahi haneli ʻōlelo, a me ke ʻano hoʻokomo piha no ka poʻe aʻo.","p-engines.name":"Nā ʻenekini AI hou aʻe","p-engines.line":"E koho iā Claude, Codex a i ʻole Gemini no kēlā me kēia mea hana.","p-pro.name":"Hana loea","p-pro.line":"Nā lepili pilikia, nā puka hoʻohui, nā kāleka hanana a me nā pale.","p-self.name":"Ka mālama ʻana iā ʻoe","p-self.line":"Ke ʻano luhi, nā hoʻomanaʻo mālama iā ʻoe iho a me 4:20.","p-servers.name":"Nā kikowaena a me ka nui","p-servers.line":"Nā hoʻonohonoho kikowaena āpau, nā kuleana a me ka hoʻolālā ulu.","p-livestream.name":"Nā mea hou o ka kahe","p-livestream.line":"Ke kamaʻilio Twitch, nā emoji ponoʻī a me kahi nānā ola lehulehu."},"words":{"button":"📖 Nā huaʻōlelo mea hoʻomohala","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"E ʻimi i huaʻōlelo…","none":"ʻAʻohe huaʻōlelo e like me ia.","close":"Pani","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Ka waihona code o ka papahana a me kona moʻolelo piha o nā commits, mālama ʻia pinepine ma GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"He laina hana ʻokoʻa i loko o ke code, i hiki ke hana i nā hoʻololi me ka hoʻopā ʻole i ka mana nui.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"He kiʻi mālama ʻia o ke code, me kahi memo pōkole o ka mea i loli. Hiki iā ʻoe ke hoʻi i kekahi i nā manawa a pau.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Ka hoʻouna ʻana i nā kiʻi mālama ʻia (commits) mai kēia kamepiula a i GitHub, i mālama ʻia a kaʻana like ʻia."},{"id":"merge","g":"build","word":"Merge","text":"Ka hoʻohui hou ʻana i nā hoʻololi o kahi lālā i ka mana nui."},{"id":"pr","g":"build","word":"Pull request","text":"Ka noi e nānā ʻia a hui ʻia nā hoʻololi o kahi lālā i ka mana nui.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ka hoʻomaʻemaʻe ʻana i ke code me ka hoʻololi ʻole i kāna hana: nā waihona liʻiliʻi, nā inoa akaka, emi ka hoʻopaneʻe."},{"id":"bug","g":"build","word":"Bug","text":"ʻO kahi mea i hana ʻole e like me ka mea pono.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Ka hoʻāʻo ʻana i kahi hana i pau e nānā inā hana ia e like me ka mea i noi ʻia, ma mua o kou ʻae ʻana.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ka kau ʻana i kahi mana hou i ke ola, e laʻa ma kahi kikowaena e hoʻohana ai nā kānaka."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Nā manaʻo a me nā hana i hoʻolālā ʻole ʻia. ʻAʻohe mea ma laila e hana ʻia a neʻe i Hana."},{"id":"sprint","g":"team","word":"Sprint","text":"He manawa pōkole o ka hana (ʻo ka pule a ʻelua pule paha) me kahi pūʻulu kāleka i ʻae ʻia e hoʻopau.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"He nānā wikiwiki: ka mea i hana ai kēlā me kēia lālā, ka mea e hana ai ma hope, a me ka mea e kāohi ana iā ia.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"He papa me nā kolamu (Hana, Ke hana nei, Pau) kahi e neʻe ai nā kāleka mai ka hema a ka ʻākau i ka hana ʻana o ka hana."},{"id":"wip","g":"team","word":"WIP limit","text":"Hana e holo ana: ka nui loa o nā kāleka e paʻa ai kahi kolamu, i hoʻopau ka pūʻulu i nā mea ma mua o ka hoʻomaka ʻana i nā mea hou.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"He AI e hana ana ma ia iho i kahi hana: heluhelu i ke code, hana i nā hoʻololi, holo i nā nānā, a hōʻike hou mai.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Ke anakuhi e helu ʻia ai ka hoʻohana AI: ma kahi o kekahi mau huapalapala o ka kikokiko i heluhelu ʻia a kākau ʻia paha. ʻO ka emi o nā hōʻailona, ʻo ka nui aʻe ia o kāu papahana i koe.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"He kauoha liʻiliʻi e holo ana ma ia iho i kahi manawa i koho ʻia, e laʻa i ka hoʻomaka ʻana o kahi kau AI, i lohe ai ka pūʻulu i kāu mau ʻōlelo.","also":["hooks"]}]}};
